package ru.folio.notes;

import android.graphics.*;
import android.os.SystemClock;
import android.view.*;

/** Animated vector explanations, one feature per scene, with a static reduced-motion state. */
final class FeatureDemo extends View {
    final MainActivity a;final Paint p=new Paint(3);int scene;long started=SystemClock.uptimeMillis();float frozen=-1;String tool="brush";float strokeWidth=12,eraserRadius=37;int ink=0xff7872b7;boolean wholeAction;final Ink.Stroke sample=new Ink.Stroke();
    FeatureDemo(MainActivity a,int scene){super(a);this.a=a;this.scene=scene;setContentDescription(new String[]{"Демонстрация нажима пера","Демонстрация предпросмотра ластика","Демонстрация круговой палитры","Демонстрация отмены двумя пальцами","Демонстрация циркуля","Демонстрация перелистывания страниц","Демонстрация настройки пенала","Демонстрация экспорта"}[scene]);}
    void scene(int next){scene=next;started=SystemClock.uptimeMillis();invalidate();}
    float progress(){return frozen>=0?frozen:Studio.motion()?((SystemClock.uptimeMillis()-started)%5200)/5200f:.64f;}
    static float ease(float n){n=Ink.clamp(n,0,1);return n*n*(3-2*n);}
    protected void onDraw(Canvas c){super.onDraw(c);float k=Math.min(getWidth()/620f,getHeight()/430f);c.save();c.translate((getWidth()-620*k)/2,(getHeight()-430*k)/2);c.scale(k,k);float t=progress();
        p.setStyle(Paint.Style.FILL);p.setColor(Studio.CREAM);c.drawRoundRect(new RectF(0,0,620,430),28,28,p);p.setColor(0xffe5e2d5);p.setStrokeWidth(.6f);for(int x=28;x<620;x+=24)c.drawLine(x,58,x,402,p);for(int y=65;y<425;y+=24)c.drawLine(20,y,600,y,p);label(c,"folio",27,34,15,0xff7d7b72);label(c,"ЛИСТ ДЛЯ ВАШИХ ИДЕЙ",370,34,9,0xff99978d);
        switch(scene){case 0:writing(c,t);break;case 1:eraser(c,t);break;case 2:palette(c,t);break;case 3:undo(c,t);break;case 4:compass(c,t);break;case 5:pages(c,t);break;case 6:tools(c,t);break;case 7:export(c,t);break;}
        c.restore();if(frozen<0&&Studio.motion()&&hasWindowFocus()&&isShown())postInvalidateOnAnimation();
    }
    void label(Canvas c,String s,float x,float y,float size,int color){p.setShader(null);p.setStyle(Paint.Style.FILL);p.setTypeface(Typeface.create("sans-serif-medium",0));p.setTextSize(size);p.setColor(color);c.drawText(s,x,y,p);}
    void tag(Canvas c,String s,int color){p.setColor(color);c.drawRoundRect(new RectF(24,369,300,407),19,19,p);label(c,s,42,394,12,0xff353945);}
    float[] wave(float q){return new float[]{75+q*452,225+(float)Math.sin(q*Math.PI*3.4)*45};}
    void line(Canvas c,float from,float to,float alpha){p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);for(int i=1;i<=100;i++){float q=i/100f;if(q<from||q>to)continue;float[] x=wave(q-.01f),y=wave(q);p.setColor(ink);p.setAlpha((int)(alpha*255));p.setStrokeWidth(strokeWidth*(.3f+.8f*(float)Math.sin(q*Math.PI)));c.drawLine(x[0],x[1],y[0],y[1],p);}p.setAlpha(255);p.setStyle(Paint.Style.FILL);}
    void pen(Canvas c,float x,float y,float size){c.save();c.rotate(153,x,y);ToolArt.draw(c,tool,x,y,size,ink);c.restore();}
    void writing(Canvas c,float t){float q=ease(t/.72f);sample.points.clear();sample.tool=tool;sample.width=strokeWidth;sample.color=tool.equals("laser")?0xffef7486:ink;
        boolean geometry=java.util.Arrays.asList("line","arrow","rect","ellipse","triangle","text").contains(tool);
        if(geometry){sample.points.add(new Ink.Pt(135,155,1,0,0));sample.points.add(new Ink.Pt(475,290,1,0,0));if(tool.equals("triangle")){sample.points.clear();for(float[] point:new float[][]{{310,115},{475,300},{145,300},{310,115}})sample.points.add(new Ink.Pt(point[0],point[1],1,0,0));}if(tool.equals("arrow")){sample.points.add(new Ink.Pt(440,250,1,0,0));sample.points.add(new Ink.Pt(475,290,1,0,0));sample.points.add(new Ink.Pt(425,298,1,0,0));}if(tool.equals("text")){sample.text="Ваша идея";sample.width=35;}c.save();c.clipRect(0,0,620*q,430);InkRenderer.stroke(c,sample);c.restore();}
        else {for(int i=0;i<=100*q;i++){float u=i/100f;float[] point=wave(u);sample.points.add(new Ink.Pt(point[0],point[1],.15f+.85f*(float)Math.sin(u*Math.PI),.2f,-.4f));}InkRenderer.stroke(c,sample);float[] end=wave(q);pen(c,end[0],end[1],1.45f);}
        tag(c,java.util.Arrays.asList("brush","pen","pencil","fountain").contains(tool)?"МЕНЬШЕ НАЖИМ  →  ТОНЬШЕ ЛИНИЯ":"ПРЕДПРОСМОТР  /  "+Ink.label(tool).toUpperCase(java.util.Locale.ROOT),0xffddd9ef);}
    void eraser(Canvas c,float t){float x=100+ease(t/.7f)*420,y=wave((x-75)/452)[1],r=eraserRadius;boolean hover=t<.8f;c.save();if(hover){Path hole=new Path();hole.addCircle(x,y,r,Path.Direction.CW);c.clipOutPath(hole);}if(!wholeAction||!hover)line(c,0,1,1);c.restore();p.setColor(0xff8884b4);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.5f);c.drawCircle(x,y,r,p);p.setStyle(Paint.Style.FILL);p.setColor(0xff8884b4);c.drawCircle(x,y,2,p);c.save();c.rotate(153,x,y);ToolArt.draw(c,"eraser",x,y,1.1f,ink);c.restore();tag(c,hover?"НАВЕДЕНИЕ  /  ПРЕДПРОСМОТР":"ОТВЕДИТЕ ПЕРО  /  ШТРИХ ВЕРНУЛСЯ",0xffe1d9e7);}
    void palette(Canvas c,float t){float reveal=ease((t-.08f)/.23f);float x=300,y=232;p.setColor(0x141e2433);c.drawCircle(x,y,119*reveal,p);p.setColor(0xfffcfaf4);c.drawCircle(x,y,108*reveal,p);p.setColor(0xffe9e4f0);c.drawCircle(x,y,46*reveal,p);String[] ids={"pen","pencil","brush","marker","eraser","lasso","fountain","hand"};for(int i=0;i<8;i++){double angle=(i*45-90)*Math.PI/180;float px=x+(float)Math.cos(angle)*76*reveal,py=y+(float)Math.sin(angle)*76*reveal;Icons.draw(c,ids[i],px,py,23*reveal,0xff686180);}int[] colors={0xffaaa4d6,0xff7eb4a5,0xffd59ba7,0xffe2bf73};for(int i=0;i<4;i++){double ang=i*Math.PI/2;p.setColor(colors[i]);c.drawCircle(x+(float)Math.cos(ang)*23*reveal,y+(float)Math.sin(ang)*23*reveal,8*reveal,p);}pen(c,452,250,1.9f);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setColor(0xffaaa4d6);c.drawCircle(500,162,16+10*(float)Math.sin(t*Math.PI*4),p);p.setStyle(Paint.Style.FILL);tag(c,"ДВА СЖАТИЯ  →  ПАЛИТРА РЯДОМ",0xffddd9ef);}
    void undo(Canvas c,float t){for(int j=0;j<3;j++){p.setColor(new int[]{0xff8780b7,0xff8eb8a5,0xffcc9aa6}[j]);p.setAlpha(j==2?(int)(255*(1-ease((t-.4f)/.25f))):255);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(8);p.setStrokeCap(Paint.Cap.ROUND);Path path=new Path();path.moveTo(100,130+j*65);path.cubicTo(210,80+j*65,310,190+j*65,476,130+j*65);c.drawPath(path,p);}p.setAlpha(255);p.setStyle(Paint.Style.FILL);float pulse=ease((t-.25f)/.16f)*(1-ease((t-.7f)/.15f));for(int j=0;j<2;j++){p.setColor(0x28716ba8);c.drawCircle(275+j*52,322,22+10*pulse,p);p.setColor(0xffb9b2d6);c.drawCircle(275+j*52,322,13,p);}tag(c,"ДВА ПАЛЬЦА  /  ОДИН ШАГ НАЗАД",0xffdbe7dc);}
    void compass(Canvas c,float t){float sweep=ease(t/.8f)*360,cx=278,cy=231,r=110;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1);p.setColor(0xffc9c3d5);c.drawCircle(cx,cy,r,p);p.setStrokeWidth(4);p.setColor(ink);c.drawArc(new RectF(cx-r,cy-r,cx+r,cy+r),-90,sweep,false,p);float angle=(float)Math.toRadians(sweep-90),ex=cx+r*(float)Math.cos(angle),ey=cy+r*(float)Math.sin(angle),jx=(cx+ex)/2+30,jy=(cy+ey)/2-125;p.setStrokeWidth(9);p.setColor(0xff84908d);c.drawLine(cx,cy,jx,jy,p);p.setColor(0xffb3956e);c.drawLine(jx,jy,ex,ey,p);p.setStyle(Paint.Style.FILL);p.setColor(0xff454f51);c.drawCircle(jx,jy,9,p);c.drawCircle(cx,cy,4,p);label(c,"R 110",432,271,22,0xff77728a);tag(c,"ЗАДАЙТЕ ЦЕНТР. ВЫБЕРИТЕ РАДИУС.",0xffe8decb);}
    void pages(Canvas c,float t){float q=ease((t-.15f)/.55f);for(int j=2;j>=0;j--){float shift=j*15-(j==0?q*280:0),alpha=j==0?1-q:1;p.setColor(Studio.blend(Studio.CREAM,Color.WHITE,.25f+j*.2f));p.setAlpha((int)(255*alpha));RectF rect=new RectF(173+shift,78+j*8,428+shift,336+j*8);c.drawRoundRect(rect,12,12,p);p.setAlpha(255);p.setStyle(Paint.Style.STROKE);p.setColor(0xffccc8bb);p.setStrokeWidth(1);c.drawRoundRect(rect,12,12,p);p.setStyle(Paint.Style.FILL);label(c,"0"+(j+1),195+shift,120+j*8,17,0xff929083);for(int line=0;line<4;line++){p.setColor(0xffd7d2c3);c.drawRoundRect(new RectF(196+shift,154+line*29+j*8,389+shift,157+line*29+j*8),2,2,p);}}tag(c,"СВАЙП  →  СЛЕДУЮЩАЯ СТРАНИЦА",0xffdce4e9);}
    void tools(Canvas c,float t){String[] ids={"fountain","brush","pencil","marker","eraser","lasso"};float swap=ease((t-.15f)/.45f);p.setColor(0xff252a32);c.drawRoundRect(new RectF(65,127,555,307),28,28,p);for(int i=0;i<6;i++){float x=110+i*80;if(i==1)x+=160*swap;if(i==3)x-=160*swap;float y=i==1?148-22*(float)Math.sin(swap*Math.PI):162;if(ToolArt.nib(ids[i]))ToolArt.draw(c,ids[i],x,y,1.5f,ink);else Icons.draw(c,ids[i],x,232,40,0xffc9c5e4);}tag(c,"ВАШИ ИНСТРУМЕНТЫ. ВАШ ПОРЯДОК.",0xffddd9ef);}
    void export(Canvas c,float t){float fly=ease((t-.1f)/.6f);p.setColor(0xfffdfbf4);c.drawRoundRect(new RectF(85,100,270,326),14,14,p);label(c,"Мои идеи",110,146,18,0xff77728a);for(int i=0;i<5;i++){p.setColor(0xffdad5c5);c.drawRoundRect(new RectF(111,177+i*23,230,180+i*23),2,2,p);}for(int i=0;i<3;i++){float x=354+22*(1-fly),y=103+i*76;p.setColor(new int[]{0xffdcd6f0,0xffe7d9ce,0xffd6e4dc}[i]);p.setAlpha((int)(255*fly));c.drawRoundRect(new RectF(x,y,535+22*(1-fly),y+59),16,16,p);p.setAlpha(255);label(c,new String[]{".folio",".pdf",".png"}[i],x+21,y+36,18,0xff595966);}Icons.draw(c,"export",310,218,28,0xff8d86ae);tag(c,"ВАШИ ЗАПИСИ ВСЕГДА С ВАМИ",0xffdbe7dc);}
    public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)invalidate();}
}
